module v2_voice_engine_mux #(parameter integer VOICES=32)(input logic clk,rst_n,input logic sample_ce,input logic event_valid,output logic event_ready,input logic [95:0] event_data,output logic signed [15:0] mixed_sample,output logic sample_valid,output logic [VOICES-1:0] active_bitmap,output logic voice_overflow,output logic [7:0] revoice_count,output logic [5:0] active_voice_count);
 logic [31:0] phase[0:VOICES-1],step[0:VOICES-1];logic [7:0] note[0:VOICES-1],gain[0:VOICES-1];logic [VOICES-1:0] active;logic [5:0] rr;logic [31:0] rom_step;integer i,slot,k;logic found;v2_note_increment_rom rom(.note(event_data[71:64]),.increment(rom_step));assign active_bitmap=active;assign event_ready=rst_n;always_comb begin active_voice_count=0;for(k=0;k<VOICES;k=k+1)active_voice_count+=active[k];end
 always_ff @(posedge clk or negedge rst_n) begin if(!rst_n)begin active<=0;voice_overflow<=0;revoice_count<=0;rr<=0;sample_valid<=0;mixed_sample<=0;for(i=0;i<VOICES;i=i+1)begin phase[i]<=0;step[i]<=0;note[i]<=0;gain[i]<=0;end end else begin sample_valid<=0;if(event_valid)begin found=0;slot=0;if(event_data[94:91]==1)begin for(i=0;i<VOICES;i=i+1)if(!active[i]&&!found)begin found=1;slot=i;end;if(found)begin active[slot]<=1;note[slot]<=event_data[71:64];step[slot]<=rom_step;gain[slot]<=event_data[63:56];phase[slot]<=0;end else voice_overflow<=1;end else if(event_data[94:91]==2)begin for(i=0;i<VOICES;i=i+1)if(active[i]&&note[i]==event_data[71:64])begin gain[i]<=0;active[i]<=0;end end else if(event_data[94:91]==3)begin for(i=0;i<VOICES;i=i+1)if(active[i]&&note[i]==event_data[71:64])revoice_count<=revoice_count+1;end end if(sample_ce)begin sample_valid<=1;if(active[rr])begin phase[rr]<=phase[rr]+step[rr];mixed_sample<=($signed({1'b0,phase[rr][31:16]})-32768)>>>4;if(gain[rr]>0)gain[rr]<=gain[rr]-1;else active[rr]<=0;end else mixed_sample<=0;rr<=rr+1;end end end
endmodule
